#include <vector>

class Solution {
public:
    int sumOddLengthSubarrays(std::vector<int>& arr) {
        int n = arr.size(), ans = 0;
        for (int i = 0; i < n; ++i) {
            int total = (i + 1) * (n - i);
            int odd = (total + 1) / 2;
            ans += arr[i] * odd;
        }
        return ans;
    }
};

class Solution {
    public int sumOddLengthSubarrays(int[] arr) {
        int n = arr.length, ans = 0;
        for (int i = 0; i < n; i++) {
            int total = (i + 1) * (n - i);
            int odd = (total + 1) / 2;
            ans += arr[i] * odd;
        }
        return ans;
    }
}

var sumOddLengthSubarrays = function(arr) {
    const n = arr.length;
    let ans = 0;
    for (let i = 0; i < n; i++) {
        const total = (i + 1) * (n - i);
        const odd = Math.floor((total + 1) / 2);
        ans += arr[i] * odd;
    }
    return ans;
};
